524  static bool parse_headers(struct lwan_request_parser_helper *helper,
   525                            char *buffer)
   526  {
   527      char *buffer_end = helper->buffer->value + helper->buffer->len;
   528      char **header_start = helper->header_start;
   529      char *p;
   530      size_t n_headers = 0;
   531      bool ret = false;
   532
   533      for (p = buffer + 1; n_headers < N_HEADER_START && buffer_end > p;) {
   534          char *next_chr = p;
   535          char *next_hdr = memchr(next_chr, '\r', (size_t)(buffer_end - p));
   536
   537          if (!next_hdr)
   538              goto process;
   539
   540          if (next_chr == next_hdr) {
   541              STRING_SWITCH_SMALL(next_hdr) {
   542              case MULTICHAR_CONSTANT_SMALL('\r', '\n'):
   543                  helper->next_request = next_hdr + 2;
   544              }
   545              goto process;
   546          }
   547
   548          header_start[n_headers++] = next_chr;
   549          header_start[n_headers++] = next_hdr;
   550
   551          p = next_hdr + 2;
   552      }
   553
   554      goto out; /* Header array isn't large enough */
   555
   556  process:
   557      ret = true;
   558
   559      for (size_t i = 0; i < n_headers; i += 2) {
   560          char *end = header_start[i + 1];
   561
   562          p = header_start[i];
   563
   564          STRING_SWITCH_L (p) {
   565          case MULTICHAR_CONSTANT_L('A', 'c', 'c', 'e'):
   566              p += HEADER_LENGTH("Accept");
   567
   568              STRING_SWITCH_L (p) {
   569              case MULTICHAR_CONSTANT_L('-', 'E', 'n', 'c'):
   570                  helper->accept_encoding = HEADER("-Encoding");
   571                  break;
   572              }
   573              break;
   574          case MULTICHAR_CONSTANT_L('A', 'u', 't', 'h'):
   575              helper->authorization = HEADER("Authorization");
   576              break;
   577          case MULTICHAR_CONSTANT_L('C', 'o', 'n', 'n'):
   578              helper->connection = HEADER("Connection");
   579              break;
   580          case MULTICHAR_CONSTANT_L('C', 'o', 'n', 't'):
   581              p += HEADER_LENGTH("Content");
   582
   583              STRING_SWITCH_L (p) {
   584              case MULTICHAR_CONSTANT_L('-', 'T', 'y', 'p'):
   585                  helper->content_type = HEADER("-Type");
   586                  break;
   587              case MULTICHAR_CONSTANT_L('-', 'L', 'e', 'n'):
   588                  helper->content_length = HEADER("-Length");
   589                  break;
   590              }
   591              break;
   592          case MULTICHAR_CONSTANT_L('C', 'o', 'o', 'k'):
   593              helper->cookie = HEADER("Cookie");
   594              break;
   595          case MULTICHAR_CONSTANT_L('I', 'f', '-', 'M'):
   596              helper->if_modified_since.raw = HEADER("If-Modified-Since");
   597              break;
   598          case MULTICHAR_CONSTANT_L('R', 'a', 'n', 'g'):
   599              helper->range.raw = HEADER("Range");
   600              break;
   601          }
   602      }
   603
   604  out:
   605      helper->n_header_start = n_headers;
   606      return ret;
   607  }
   608  #undef HEADER_LENGTH
   609  #undef HEADER
