  1187  static enum lwan_http_status parse_http_request(struct lwan_request *request)
  1188  {
  1189      struct lwan_request_parser_helper *helper = request->helper;
  1190      char *buffer = helper->buffer->value;
  1191
  1192      if (request->flags & REQUEST_ALLOW_PROXY_REQS) {
  1193          /* REQUEST_ALLOW_PROXY_REQS will be cleared in lwan_process_request() */
  1194
  1195          buffer = parse_proxy_protocol(request, buffer);
  1196          if (UNLIKELY(!buffer))
  1197              return HTTP_BAD_REQUEST;
  1198      }
  1199
  1200      buffer = ignore_leading_whitespace(buffer);
  1201
  1202      char *path = identify_http_method(request, buffer);
  1203      if (UNLIKELY(!path))
  1204          return HTTP_NOT_ALLOWED;
  1205
  1206      buffer = identify_http_path(request, path);
  1207      if (UNLIKELY(!buffer))
  1208          return HTTP_BAD_REQUEST;
  1209
  1210      if (UNLIKELY(!parse_headers(helper, buffer)))
  1211          return HTTP_BAD_REQUEST;
  1212
  1213      ssize_t decoded_len = url_decode(request->url.value);
  1214      if (UNLIKELY(decoded_len < 0))
  1215          return HTTP_BAD_REQUEST;
  1216      request->original_url.len = request->url.len = (size_t)decoded_len;
  1217
  1218      parse_connection_header(request);
  1219
  1220      return HTTP_OK;
  1221  }
